public with sharing class ShipmentEventHandler {
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Deduplicate by order number - last one in list wins
        Map<String, FB_Shipment_Event__e> latestEventsByOrderNumber = new Map<String, FB_Shipment_Event__e>();
        Set<String> orderNumbersToFind = new Set<String>();

        for (FB_Shipment_Event__e event : events) {
            String orderNumber = event.Order_Number__c;
            if (String.isBlank(orderNumber)) {
                continue;
            }

            // Last event for same order number wins by overwriting in map
            latestEventsByOrderNumber.put(orderNumber, event);
            orderNumbersToFind.add(orderNumber);
        }

        if (orderNumbersToFind.isEmpty()) {
            return;
        }

        // Query matching orders in a single SOQL
        List<FB_Sales_Order__c> matchingOrders = [
            SELECT Id, Order_Number__c, Status__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :orderNumbersToFind
        ];

        // Prepare updates - skip cancelled orders
        List<FB_Sales_Order__c> ordersToUpdateFinal = new List<FB_Sales_Order__c>();

        for (FB_Sales_Order__c order : matchingOrders) {
            FB_Shipment_Event__e correspondingEvent = latestEventsByOrderNumber.get(order.Order_Number__c);

            if (correspondingEvent != null && order.Status__c != 'Cancelled') {
                order.Status__c = 'Shipped';
                order.Tracking_Number__c = correspondingEvent.Tracking_Number__c;
                order.Carrier__c = correspondingEvent.Carrier__c;
                order.Shipped_Date__c = Date.today();
                ordersToUpdateFinal.add(order);
            }
        }

        if (!ordersToUpdateFinal.isEmpty()) {
            update ordersToUpdateFinal;
        }
    }
}
