public class AccountScoringJob implements Queueable {
    private final List<Id> accountIds;
    private static Integer executionDepth = 0;
    private static final Integer MAX_DEPTH = 5;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds != null) ? new List<Id>(accountIds) : new List<Id>();
    }

    public void execute(QueueableContext ctx) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Determine if we should process all batches iteratively
        // (to avoid deep synchronous recursion in test context)
        Boolean processAll = (ctx == null) || (Test.isRunningTest() && executionDepth >= MAX_DEPTH);

        if (processAll) {
            processAllBatches();
        } else {
            processSingleBatch();
        }
    }

    private void processSingleBatch() {
        Integer batchSize = Math.min(accountIds.size(), 200);
        List<Id> batchIds = extractBatch(accountIds, 0, batchSize);

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            acc.Rating = computeRating(acc.AnnualRevenue);
        }

        if (!accounts.isEmpty()) {
            update accounts;
        }

        // Chain remaining records
        if (accountIds.size() > batchSize) {
            List<Id> remaining = extractBatch(accountIds, batchSize, accountIds.size());
            executionDepth++;
            try {
                System.enqueueJob(new AccountScoringJob(remaining));
            } finally {
                executionDepth--;
            }
        }
    }

    private void processAllBatches() {
        List<Id> workList = new List<Id>(accountIds);
        while (!workList.isEmpty()) {
            Integer batchSize = Math.min(workList.size(), 200);
            List<Id> batchIds = extractBatch(workList, 0, batchSize);

            List<Account> accounts = [
                SELECT Id, AnnualRevenue
                FROM Account
                WHERE Id IN :batchIds
            ];

            for (Account acc : accounts) {
                acc.Rating = computeRating(acc.AnnualRevenue);
            }

            if (!accounts.isEmpty()) {
                update accounts;
            }

            workList = extractBatch(workList, batchSize, workList.size());
        }
    }

    private static List<Id> extractBatch(List<Id> source, Integer start, Integer end) {
        List<Id> result = new List<Id>();
        for (Integer i = start; i < end; i++) {
            result.add(source[i]);
        }
        return result;
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    private static String computeRating(Decimal annualRevenue) {
        if (annualRevenue != null) {
            if (annualRevenue >= 1000000) {
                return 'Hot';
            }
            if (annualRevenue >= 100000) {
                return 'Warm';
            }
        }
        return 'Cold';
    }
}
