public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public override void onAfterInsert(Map<Id, SObject> mapNew) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (SObject record : mapNew.values()) {
            if (((Opportunity) record).StageName == 'Closed Won') {
                qualifyingIds.add((Id) record.get('Id'));
            }
        }
        startFulfilmentFor(qualifyingIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> mapOld, Map<Id, SObject> mapNew) {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Id oppId : mapNew.keySet()) {
            Opportunity newOpp = (Opportunity) mapNew.get(oppId);
            Opportunity oldOpp = (Opportunity) mapOld.get(oppId);
            if (newOpp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                qualifyingIds.add(oppId);
            }
        }
        startFulfilmentFor(qualifyingIds);
    }

    private void startFulfilmentFor(Set<Id> opportunityIds) {
        if (!opportunityIds.isEmpty()) {
            ((IOpportunityFulfilmentService)
                Application.Service.newInstance(IOpportunityFulfilmentService.class)
            ).startFulfilment(opportunityIds);
        }
    }
}
