public with sharing class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> childIds = parentIdByChildId.keySet();
        Set<Id> parentIds = new Set<Id>(parentIdByChildId.values());

        // Query existing relationships between any child-parent pair (both directions)
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c, npe4__Type__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
               OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ];

        // Build a set of existing relationship directional pairs for quick lookup
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : existingRels) {
            existingPairs.add(
                String.valueOf(rel.npe4__Contact__c) + '|' + String.valueOf(rel.npe4__RelatedContact__c)
            );
        }

        // Collect new child-to-parent relationships to create
        // NPSP's Relationship trigger will automatically create the reciprocal 
        // parent-to-child relationships (Son/Daughter/Child) based on the 
        // Relationship Lookup configuration
        List<npe4__Relationship__c> relsToCreate = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            String childToParentKey = String.valueOf(childId) + '|' + String.valueOf(parentId);
            String parentToChildKey = String.valueOf(parentId) + '|' + String.valueOf(childId);

            // Skip if either direction already exists
            if (existingPairs.contains(childToParentKey) || existingPairs.contains(parentToChildKey)) {
                continue;
            }

            relsToCreate.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        if (!relsToCreate.isEmpty()) {
            insert relsToCreate;
        }
    }
}
