public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        // Check if the running user has read access to the FB_Employee__c object
        if (!Schema.sObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Build a set of readable fields to include in the SOQL query
        Set<String> readableFields = new Set<String>{ 'Id', 'Name' };

        // Check field-level read access for each custom field
        if (Schema.sObjectType.FB_Employee__c.fields.Department__c.isAccessible()) {
            readableFields.add('Department__c');
        }
        if (Schema.sObjectType.FB_Employee__c.fields.Salary__c.isAccessible()) {
            readableFields.add('Salary__c');
        }
        if (Schema.sObjectType.FB_Employee__c.fields.Personal_Email__c.isAccessible()) {
            readableFields.add('Personal_Email__c');
        }

        // Query only the fields the running user can read, ordered by Name ASC
        String soql = 'SELECT ' + String.join(readableFields, ', ') + 
                      ' FROM FB_Employee__c ORDER BY Name ASC';

        return Database.query(soql);
    }
}
